THRESHOLDS = [(1000, "1km 앞"), (300, "300m 앞"), (50, "곧")]

def announcer():
    said = set()
    def on_progress(dist_m, maneuver):
        out = []
        for limit, label in THRESHOLDS:
            if dist_m <= limit and limit not in said:
                said.add(limit)
                out.append(f"{label} {maneuver}")
        return out[-1] if out else None
    return on_progress

say = announcer()
for d in [1500, 980, 640, 290, 120, 40, 10]:
    print(d, say(d, "우회전") or "-")
# 1500 - / 980 1km 앞 우회전 / 640 - / 290 300m 앞 우회전 / 120 - / 40 곧 우회전 / 10 -
